<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { documentosApi } from '../api/resources'; import { errorMessage } from '../api/client'; import type { Documento, Page } from '../types'
const router = useRouter(); const page = ref<Page<Documento> | null>(null); const municipio = ref(''); const periodo = ref(''); const loading = ref(false); const error = ref('')
const date = (v: string) => new Date(v).toLocaleString('pt-BR')
async function load(index = 0) { loading.value = true; error.value = ''; try { page.value = (await documentosApi.listar({ municipio: municipio.value || undefined, periodo: periodo.value || undefined, page: index, size: 20 })).data } catch (e) { error.value = errorMessage(e) } finally { loading.value = false } }
async function remove(id: number) { if (!confirm('Excluir este documento e seu arquivo? Esta ação não pode ser desfeita.')) return; try { await documentosApi.excluir(id); await load(page.value?.number || 0) } catch (e) { error.value = errorMessage(e) } }
onMounted(load)
</script>
<template><section class="page"><header class="page-header"><div><p class="eyebrow">Gestão</p><h1>Documentos</h1></div><RouterLink class="primary button" to="/documentos/novo">Novo documento</RouterLink></header><form class="filters" @submit.prevent="load(0)"><input v-model="municipio" placeholder="Filtrar por município" /><input v-model="periodo" placeholder="Período (MM-AAAA)" /><button class="secondary">Filtrar</button></form><p v-if="error" class="alert error">{{ error }}</p><div class="card table-wrap"><p v-if="loading" class="muted">Carregando...</p><table v-else><thead><tr><th>Documento</th><th>Município</th><th>Período</th><th>Tipo</th><th>Links</th><th>Upload</th><th></th></tr></thead><tbody><tr v-for="doc in page?.content" :key="doc.id"><td><strong>{{ doc.nomeOriginal }}</strong></td><td>{{ doc.municipio }}</td><td>{{ doc.periodoFormatado }}</td><td>{{ doc.tipoImposto.sigla }}</td><td>{{ doc.quantidadeLinks }}</td><td>{{ date(doc.dataUpload) }}</td><td class="actions"><RouterLink :to="`/documentos/${doc.id}`">Abrir</RouterLink><button class="danger-text" @click="remove(doc.id)">Excluir</button></td></tr><tr v-if="!page?.content.length"><td colspan="7" class="muted">Nenhum documento encontrado.</td></tr></tbody></table></div><footer v-if="page" class="pager"><button :disabled="page.first" @click="load(page.number - 1)">Anterior</button><span>Página {{ page.number + 1 }} de {{ page.totalPages || 1 }}</span><button :disabled="page.last" @click="load(page.number + 1)">Próxima</button></footer></section></template>